contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 balAfterDeposit = c.balances(msg.sender); if (__ESBMC_reverted()) return;

        uint256 minSum = c.MinSum(); if (__ESBMC_reverted()) return;
        require(balAfterDeposit >= minSum);

        uint256 contractBalBeforeCollect = address(c).balance;

        c.Collect(amount); if (__ESBMC_reverted()) return;

        uint256 balAfterCollect = c.balances(msg.sender); if (__ESBMC_reverted()) return;

        assert(balAfterCollect == balAfterDeposit - amount);
    }
}

