        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 balAfterDeposit;
        try c.balances(msg.sender) returns (uint256 __r) { balAfterDeposit = __r; } catch { return; }
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        vm.assume(balAfterDeposit >= minSum);
        uint256 contractBalBeforeCollect = address(c).balance;
        try c.Collect(amount) {} catch { return; }
        uint256 balAfterCollect;
        try c.balances(msg.sender) returns (uint256 __r) { balAfterCollect = __r; } catch { return; }
        assertTrue(balAfterCollect == balAfterDeposit - amount);
